static bool s_spi_inited = false;

// Forward declaration of internal callback
static void spi_internal_callback(SPI_Handle handle, SPI_Transaction *transaction);

typedef struct {
    SPI_Handle handle;
    SPI_Params params;
    TUYA_SPI_BASE_CFG_T last_cfg;

    TUYA_SPI_IRQ_CB irq_cb;
    bool irq_enabled;

    volatile bool busy;
    volatile uint32_t last_count_frames;

    /* new fields for error/status tracking */
    volatile uint8_t hw_data_lost;   /* 0/1 - rx overflow / tx underflow */
    volatile uint8_t hw_mode_fault;  /* 0/1 - mode fault detected */
} tkl_spi_ctx_t;

// NO MAGIC NUMBER: Using constant from board config
static tkl_spi_ctx_t g_spi[TKL_MAX_SPI_PORTS] = {0};

static inline bool is_valid_port(TUYA_SPI_NUM_E port) {
    return (port >= TUYA_SPI_NUM_0) && (port < TKL_MAX_SPI_PORTS);
}

static inline size_t frame_bytes(const tkl_spi_ctx_t *ctx) {
    return (ctx->params.dataSize <= 8) ? 1u : 2u;
}


/**
 * @brief spi init
 *
 * @param[in] port: spi port
 * @param[in] cfg: spi config
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_init(TUYA_SPI_NUM_E port, const TUYA_SPI_BASE_CFG_T *cfg)
{
    if (!is_valid_port(port) || cfg == NULL) {
        return OPRT_INVALID_PARM;
    }

    // [MAPPING] Look up TI index dynamically
    int16_t ti_index = tkl_hw_get_spi_index((uint8_t)port);
    
    // Check if the application mapped this SPI port
    if (ti_index < 0) {
        return OPRT_NOT_SUPPORTED;
    }

    tkl_spi_ctx_t *ctx = &g_spi[port];

    /* If already open — close first to avoid leaks / conflicts */
    if (ctx->handle != NULL) {
        SPI_close(ctx->handle);
        ctx->handle = NULL;
    }

    SPI_Params_init(&ctx->params);

    /* map data bits */
    if (cfg->databits == TUYA_SPI_DATA_BIT8) {
        ctx->params.dataSize = 8;
    } else if (cfg->databits == TUYA_SPI_DATA_BIT16) {
        ctx->params.dataSize = 16;
    } else {
        return OPRT_NOT_SUPPORTED;
    }

    /* map bitrate (use cfg if >0, otherwise 1MHz default) */
    ctx->params.bitRate = (cfg->freq_hz > 0) ? cfg->freq_hz : 1000000;
    ctx->params.custom = NULL; /* set custom to NULL by default */

    /* map SPI mode (CPOL/CPHA) */
    switch (cfg->mode) {
        case TUYA_SPI_MODE0: ctx->params.frameFormat = SPI_POL0_PHA0; break;
        case TUYA_SPI_MODE1: ctx->params.frameFormat = SPI_POL0_PHA1; break;
        case TUYA_SPI_MODE2: ctx->params.frameFormat = SPI_POL1_PHA0; break;
        case TUYA_SPI_MODE3: ctx->params.frameFormat = SPI_POL1_PHA1; break;
        default: return OPRT_INVALID_PARM;
    }

    /* map role (master/slave) */
    switch (cfg->role) {
        case TUYA_SPI_ROLE_MASTER:
        case TUYA_SPI_ROLE_MASTER_SIMPLEX:
            ctx->params.mode = SPI_CONTROLLER;
            break;
        case TUYA_SPI_ROLE_SLAVE:
        case TUYA_SPI_ROLE_SLAVE_SIMPLEX:
            ctx->params.mode = SPI_PERIPHERAL;
            break;
        default:
            ctx->params.mode = SPI_CONTROLLER;
            break;
    }

    /* default to blocking transfers for now (you can change later) */
    ctx->params.transferMode = SPI_MODE_BLOCKING;
    ctx->params.transferTimeout = SPI_WAIT_FOREVER;
    ctx->params.transferCallbackFxn = NULL;

    /* ensure driver initialized and open the peripheral */
    if (!s_spi_inited) { SPI_init(); s_spi_inited = true; }
    
    // Open using mapped TI index
    ctx->handle = SPI_open((uint_least8_t)ti_index, &ctx->params);
    if (ctx->handle == NULL) {
        return OPRT_COM_ERROR;
    }

    /* save last configuration and initialize other fields */
    ctx->last_cfg = *cfg;
    ctx->busy = false;
    ctx->last_count_frames = 0;
    ctx->irq_cb = NULL;
    ctx->irq_enabled = false;
    ctx->hw_data_lost = 0;
    ctx->hw_mode_fault = 0;

    return OPRT_OK;
}


/**
 * @brief spi deinit
 *
 * @param[in] port: spi port
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_deinit(TUYA_SPI_NUM_E port)
{
    if (!is_valid_port(port)) {
        return OPRT_INVALID_PARM;
    }

    tkl_spi_ctx_t *ctx = &g_spi[port];

    /* Nothing to do if not opened */
    if (ctx->handle == NULL) {
        return OPRT_OK;
    }

    /* Cancel any in-progress queued/callback transfers.
       Safe to call even if no transfer is active. */
    SPI_transferCancel(ctx->handle);

    /* Optionally: wait a short bounded time for ctx->busy to clear.
       Avoid blocking for long periods inside deinit. */

    /* Disable any IRQ / user callback state so callbacks won't run after close */
    ctx->irq_enabled = false;
    ctx->irq_cb = NULL;

    /* Close TI driver handle and release resources */
    SPI_close(ctx->handle);
    ctx->handle = NULL;

    /* Reset params/context */
    SPI_Params_init(&ctx->params);
    ctx->last_cfg = (TUYA_SPI_BASE_CFG_T){0};
    ctx->busy = false;
    ctx->last_count_frames = 0;

    return OPRT_OK;
}
/**
 * Spi send
 *
 * @param[in]  port      the spi device
 * @param[in]  data     spi send data
 * @param[in]  size     spi send data size
 *
 * @return  OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_send(TUYA_SPI_NUM_E port, void *data, uint32_t size)
{
    if (!is_valid_port(port) || data == NULL || size == 0) {
        return OPRT_INVALID_PARM;
    }

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return OPRT_NOT_SUPPORTED;

    size_t fb = frame_bytes(ctx);
    if ((size % fb) != 0) return OPRT_INVALID_PARM;

    SPI_Transaction txn;
    memset(&txn, 0, sizeof(txn));
    txn.count = size / fb;
    txn.txBuf = data;
    txn.rxBuf = NULL;

    ctx->busy = true;
    bool ok = SPI_transfer(ctx->handle, &txn);
    ctx->busy = false;

    ctx->last_count_frames = txn.count;

    return ok ? OPRT_OK : OPRT_COM_ERROR;
}

