/**
 * @brief spi transfer
 *
 * @param[in] port: spi port
 * @param[in] send_buf: spi send buf
 * @param[out] receive_buf: spi recv buf
 * @param[in] length: spi msg length
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_transfer(TUYA_SPI_NUM_E port, void *send_buf, void *receive_buf, uint32_t length)
{
    if (!is_valid_port(port) || length == 0) {
        return OPRT_INVALID_PARM;
    }

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return OPRT_NOT_SUPPORTED;

    size_t fb = frame_bytes(ctx);
    if ((length % fb) != 0) return OPRT_INVALID_PARM;

    SPI_Transaction txn;
    memset(&txn, 0, sizeof(txn));
    txn.count = length / fb;
    txn.txBuf = send_buf;
    txn.rxBuf = receive_buf;

    ctx->busy = true;
    bool ok = SPI_transfer(ctx->handle, &txn);
    ctx->busy = false;

    ctx->last_count_frames = txn.count;

    return ok ? OPRT_OK : OPRT_COM_ERROR;
}

/**
 * @brief spi transfer with length
 *
 * @param[in] port: spi port
 * @param[in] send_buf: spi send buf
 * @param[in] send_len: send_len
 * @param[out] receive_buf: spi recv buf
 * @param[in] receive_len: receive_len
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_transfer_with_length(TUYA_SPI_NUM_E port, void *send_buf, uint32_t send_len, void *receive_buf,
                                         uint32_t receive_len)
{
    if (!is_valid_port(port)) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return OPRT_NOT_SUPPORTED;

    size_t fb = frame_bytes(ctx);

    if (send_len > 0 && (send_len % fb) != 0) return OPRT_INVALID_PARM;
    if (receive_len > 0 && (receive_len % fb) != 0) return OPRT_INVALID_PARM;

    /* if lengths equal -> single full-duplex transaction */
    if (send_len == receive_len) {
        if (send_len == 0) return OPRT_INVALID_PARM;
        SPI_Transaction txn;
        memset(&txn,0,sizeof(txn));
        txn.count = send_len / fb;
        txn.txBuf = send_buf;
        txn.rxBuf = receive_buf;

        ctx->busy = true;
        bool ok = SPI_transfer(ctx->handle, &txn);
        ctx->busy = false;

        ctx->last_count_frames = txn.count;
        return ok ? OPRT_OK : OPRT_COM_ERROR;
    }

    /* otherwise do send-only then receive-only (sequential) */
    if (send_len > 0) {
        SPI_Transaction txn;
        memset(&txn,0,sizeof(txn));
        txn.count = send_len / fb;
        txn.txBuf = send_buf;
        txn.rxBuf = NULL;

        ctx->busy = true;
        bool ok = SPI_transfer(ctx->handle, &txn);
        ctx->busy = false;

        ctx->last_count_frames = txn.count;
        if (!ok) return OPRT_COM_ERROR;
    }

    if (receive_len > 0) {
        SPI_Transaction txn;
        memset(&txn,0,sizeof(txn));
        txn.count = receive_len / fb;
        txn.txBuf = NULL;
        txn.rxBuf = receive_buf;

        ctx->busy = true;
        bool ok = SPI_transfer(ctx->handle, &txn);
        ctx->busy = false;

        ctx->last_count_frames = txn.count;
        if (!ok) return OPRT_COM_ERROR;
    }

    return OPRT_OK;
}

/**
 * @brief adort spi transfer,or spi send, or spi recv
 *
 * @param[in] port: spi port
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */

OPERATE_RET tkl_spi_abort_transfer(TUYA_SPI_NUM_E port)
{
    if (!is_valid_port(port)) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return OPRT_NOT_SUPPORTED;

    /* cancel queued/ongoing transfers (only affects callback mode transfers) */
    SPI_transferCancel(ctx->handle);

    /* best-effort mark not busy */
    ctx->busy = false;

    return OPRT_OK;
}

/**
 * @brief get spi status.
 *
 * @param[in] port: spi port
 * @param[out]  TUYA_SPI_STATUS_T,please refer to tuya_cloud_types.h
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_get_status(TUYA_SPI_NUM_E port, TUYA_SPI_STATUS_T *status)
{
    if (!is_valid_port(port) || status == NULL) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return OPRT_NOT_SUPPORTED;

    /* Fill what we can from our context. TUYA_SPI_STATUS_T contents may vary;
       here we only fill a couple typical fields if they exist. If fields differ,
       adjust accordingly. */
#ifdef TUYA_SPI_STATUS_HAS_BUSY /* optional compile-time guard - remove if not defined */
    status->busy = ctx->busy;
#endif

#ifdef TUYA_SPI_STATUS_HAS_FRAMES_TRANSFERRED
    status->frames = ctx->last_count_frames;
#endif

    /* If TUYA_SPI_STATUS_T has other fields, populate as needed. */
    return OPRT_OK;
}


/**
 * @brief spi irq init
 * NOTE: call this API will not enable interrupt
 *
 * @param[in] port: spi port, id index starts at 0
 * @param[in] cb:  spi irq cb
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_irq_init(TUYA_SPI_NUM_E port, TUYA_SPI_IRQ_CB cb)
{
    if (!is_valid_port(port)) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];

    
    ctx->irq_cb = cb;
    ctx->irq_enabled = false;

   
    ctx->params.transferCallbackFxn = spi_internal_callback;

    return OPRT_OK;
}
/**
 * @brief spi irq enable
 *
 * @param[in] port: spi port id, id index starts at 0
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_irq_enable(TUYA_SPI_NUM_E port)
{
    if (!is_valid_port(port)) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];

    /* Logical flag */
    ctx->irq_enabled = true;

    /* If not open yet - just save parameters so callback is used when opened */
    if (ctx->handle == NULL) {
        ctx->params.transferMode = SPI_MODE_CALLBACK;
        ctx->params.transferCallbackFxn = spi_internal_callback;
        return OPRT_OK;
    }

    /* Already open - if already in callback mode with wrapping cb, just enable flag */
    if (ctx->params.transferMode == SPI_MODE_CALLBACK &&
        ctx->params.transferCallbackFxn == spi_internal_callback) {
        return OPRT_OK;
    }

    /* Need to switch current open to callback mode.
       Save old params to try and restore in case of issue. */
    SPI_Params old_params;
    memcpy(&old_params, &ctx->params, sizeof(SPI_Params));

    // [MAPPING] Look up TI index dynamically
    int16_t ti_index = tkl_hw_get_spi_index((uint8_t)port);
    if (ti_index < 0) return OPRT_NOT_SUPPORTED;

    /* Close device now, change params and try to reopen */
    SPI_close(ctx->handle);
    ctx->handle = NULL;

    ctx->params.transferMode = SPI_MODE_CALLBACK;
    ctx->params.transferCallbackFxn = spi_internal_callback;

    // Use mapped index
    ctx->handle = SPI_open((uint_least8_t)ti_index, &ctx->params);
    if (ctx->handle == NULL) {
       
        ctx->params = old_params;
        ctx->handle = SPI_open((uint_least8_t)ti_index, &ctx->params);
        if (ctx->handle == NULL) {
            ctx->irq_enabled = false;
            return OPRT_COM_ERROR;
        }
       
        return OPRT_NOT_SUPPORTED;
    }

    return OPRT_OK;
}

/**
 * @brief spi irq disable
 *
 * @param[in] port: spi port id, id index starts at 0
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_irq_disable(TUYA_SPI_NUM_E port)
{
    if (!is_valid_port(port)) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];
    ctx->irq_enabled = false;

    /* Do not close or change handle state to not disrupt running transfers.
       If you want to force blocking mode, must close and reopen like in enable. */
    return OPRT_OK;
}

/**
 * @brief spi transferred data count.
 *
 * @param[in] port: spi port id, id index starts at 0
 *
 * @return >=0,number of currently transferred data items. <0,err.
 * during  tkl_spi_send, tkl_spi_recv and tkl_spi_transfer operation.
 */
int32_t tkl_spi_get_data_count(TUYA_SPI_NUM_E port)
{
    if (!is_valid_port(port)) return -1;

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return -1;

    return (int32_t)ctx->last_count_frames;
}



/**
 * @brief spi ioctl
 *
 * @param[in]       cmd     user def
 * @param[in]       args    args associated with the command
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_spi_ioctl(TUYA_SPI_NUM_E port, uint32_t cmd, void *args)
{
    if (!is_valid_port(port)) return OPRT_INVALID_PARM;

    tkl_spi_ctx_t *ctx = &g_spi[port];
    if (ctx->handle == NULL) return OPRT_NOT_SUPPORTED;

    /* Pass to extended driver call if exists */
    int_fast16_t rc = SPI_control(ctx->handle, (uint_fast16_t)cmd, args);
    if (rc >= 0) return OPRT_OK;

    /* If driver doesn't support command, return NOT_SUPPORTED - can map specific TUYA commands here */
    return OPRT_NOT_SUPPORTED;
}


/**
 * @brief spi get max supported dma data length.
 * * @param[in] NULL
 *
 * @return >=0,number of supported dma data length. <0,err. 
 * during  tkl_spi_send, tkl_spi_recv and tkl_spi_transfer operation.
 */
uint32_t tkl_spi_get_max_dma_data_length(void)
{
  

#ifdef SPICC26X2DMA_CMD_GET_MAX_XFER
    for (int port = 0; port < TKL_MAX_SPI_PORTS; ++port) {
        tkl_spi_ctx_t *ctx = &g_spi[port];
        if (ctx->handle != NULL) {
            uint32_t mx = 0;
            if (SPI_control(ctx->handle, SPICC26X2DMA_CMD_GET_MAX_XFER, &mx) == SPI_STATUS_SUCCESS) {
                return mx;
            }
        }
    }
#endif

  
    return TUYA_SPI_MAX_DMA_DEFAULT;
}

static void spi_internal_callback(SPI_Handle handle, SPI_Transaction *transaction)
{
  
    for (int port = 0; port < TKL_MAX_SPI_PORTS; ++port) {
        tkl_spi_ctx_t *ctx = &g_spi[port];
        if (ctx->handle == handle) {
            ctx->last_count_frames = transaction ? (uint32_t)transaction->count : 0;
            ctx->busy = false;

           
            if (ctx->irq_enabled && ctx->irq_cb) {
                
               ctx->irq_cb((TUYA_SPI_NUM_E)port, TUYA_SPI_EVENT_TRANSFER_COMPLETE);
            }
            break;
        }
    }
}